    [Xunit.Fact]
    public static void TestNoAgreementIsThScore() {
        // the font score without agreement is P7.0's, on a grid of components
        int m = 1000;
        int g = 0;
        int o = 0;
        int p = 0;
        while (m >= 0) {
            g = 0;
            while (g <= 1000) {
                o = 0;
                while (o <= 1000) {
                    p = 0;
                    while (p <= 4000) {
                        emon.Testport.AssertEq(Health.HhScore(m, g, o, p, -1), Tlhealth.ThScore(m, g, o, p), "hh-score is th-score without agreement");
                        p += 1333;
                    }
                    o += 250;
                }
                g += 250;
            }
            m -= 333;
        }
    }
    [Xunit.Fact]
    public static void TestBlend() {
        emon.Testport.AssertEq(Health.HhBlend(1000, 4, 1000, 3, 1000, 2, 1000, 1, 1000, 5, -1, 0), 1000, "all perfect");
        emon.Testport.AssertEq(Health.HhBlend(-1, 4, -1, 3, -1, 2, -1, 1, -1, 5, -1, 0), -1, "nothing present");
        // an absent component is ignored, never zero
        emon.Testport.AssertEq(Health.HhBlend(800, 3, -1, 3, -1, 2, -1, 2, -1, 0, -1, 0), 720, "one present: its own value, scaled by the weakest, which it is");
        emon.Testport.AssertEq(Health.HhBlend(1000, 3, 1000, 3, -1, 2, 1000, 2, -1, 0, -1, 0), 1000, "the absent one does not drag");
        // the weakest scales the harmonic mean: 15e6 / (10000 + 5e6/100) = 250, times (1000 + 100) / 2000
        emon.Testport.AssertEq(Health.HhBlend(1000, 4, 1000, 3, 1000, 2, 1000, 1, 100, 5, -1, 0), 137, "one weak component pulls the whole down");
        // agreement 0 is floored at 50 for the mean and counts as 0 for the scale
        emon.Testport.AssertEq(Health.HhBlend(1000, 4, 1000, 3, 1000, 2, 1000, 1, 0, 5, -1, 0), 68, "no agreement at all");
        emon.Testport.AssertEq(Health.HhScore(1000, 0, 0, 0, 900), 1000, "agreement 900 is fully trusted");
        emon.Testport.AssertEq(Health.HhScore(1000, 0, 0, 0, 100), 68, "agreement 100 is under the bad line: the same as none at all");
        emon.Testport.AssertEq(Health.HhOcrScore(1000, 1000, -1, 1000, -1, -1), 1000, "a clean block");
        emon.Testport.AssertEq(Health.HhRegionScore(-1, -1, 1000, 900), 899, "a region with only skew and confidence: 947 scaled by 0.95");
    }
    internal static int HtWordIn(emon.Port.Cells words, emon.Port.Cells fw, emon.Port.Cells feats, emon.Port.Cells et, int page, int font, int script) {
        // One text-layer word of `page` in `font`, its feature row of the `xt` columns a healthy font has, copied into `fw`; answers its `fw` row.
        int ts = emon.Port.CellsLen(et);
        int w = Evidence.WdNew(words, page, 0, 0, 1000, 1000, 0, 900, 1000, 900, 0, 0, ts, 2, -1, -1, -1);
        int f = Evidence.FeNew(feats, Evidence.EaWords(), w);
        int r = 0;
        if (script == 0) {
            emon.Port.CellsPush(et, 97);
            emon.Port.CellsPush(et, 98);
        } else if (script == 2) {
            emon.Port.CellsPush(et, 1488);
            emon.Port.CellsPush(et, 49);
        } else {
            emon.Port.CellsPush(et, 1488);
            emon.Port.CellsPush(et, 1489);
        }
        Evidence.WdSet(words, w, Evidence.WfFont(), font);
        Evidence.FeSet(feats, f, Evidence.XtFontHealth(), 1000);
        Evidence.WdSet(words, w, Evidence.HdFeat(), f);
        r = emon.Port.CellsLen(fw) / 24;
        Player.FwCopyWord(fw, words, w, -1);
        return r;
    }
    internal static int HtWord(emon.Port.Cells words, emon.Port.Cells fw, emon.Port.Cells feats, emon.Port.Cells et, int page, int font) {
        return HtWordIn(words, fw, feats, et, page, font, 0);
    }
    internal static int HtFontRow(emon.Port.Cells hl, int page, int font) {
        // A font-page row of P7.0's: components of a healthy font, score 1000.
        int r = Player.HlNew(hl, Player.PlhFontPage(), page, font);
        Player.HlSet(hl, r, Player.HlfMapped(), 1000);
        Player.HlSet(hl, r, Player.HlfGarbage(), 0);
        Player.HlSet(hl, r, Player.HlfOverlap(), 0);
        Player.HlSet(hl, r, Player.HlfGap(), 0);
        Player.HlSet(hl, r, Player.HlfScore(), 1000);
        return r;
    }
    internal static int HtGroup(emon.Port.Cells cg, emon.Port.Cells refs, int page, int ea, int widx, int simfold) {
        // A group of `page` with one text-layer candidate (the `ea` row `widx`) and one OCR word; its folded similarity.
        int g = Player.CgNew(cg, page, 0, 0, 1000, 1000, 0);
        int t = Evidence.RfAdd(refs, ea, widx);
        int o = Evidence.RfAdd(refs, Evidence.EaOwords(), 0);
        Player.CgSet(cg, g, Player.CgfTfirst(), t);
        Player.CgSet(cg, g, Player.CgfTcount(), 1);
        Player.CgSet(cg, g, Player.CgfOfirst(), o);
        Player.CgSet(cg, g, Player.CgfOcount(), 1);
        Player.CgSet(cg, g, Player.CgfSimfold(), simfold);
        return g;
    }
    internal static int HtGroups(emon.Port.Cells cg, emon.Port.Cells refs, int page, int ea, int widx, int total, int agreeing) {
        // `total` groups on one word, the first `agreeing` of them at similarity 950, the rest at 100.
        int i = 0;
        while (i < total) {
            if (i < agreeing) {
                HtGroup(cg, refs, page, ea, widx, 950);
            } else {
                HtGroup(cg, refs, page, ea, widx, 100);
            }
            i += 1;
        }
        return total;
    }
