        int shifted = HtWord(words, fw, feats, et, 1, 1);
        HtFontRow(hl, 1, 0);
        HtFontRow(hl, 1, 1);
        // font 0: 12 groups, 11 agree; font 1: 12 groups, 1 agrees
        HtGroups(cg, refs, 1, Player.PlEaFw(), healthy, 12, 11);
