        emon.Testport.AssertEq(Player.HlGet(hl, 1, Health.HlfAgree()), 1, "agreeing groups");
        // a second call is the same
        Health.HlPage(1, cg, refs, fw, words, et, feats, ob, ol, ow, hl);
        emon.Testport.AssertEq(Player.HlCount(hl), 2, "no row is added");
        emon.Testport.AssertEq(HtAgreementOf(hl, 1, 1), 83, "and no count doubles");
    }
