    internal static int HtOcrWord(emon.Port.Cells ow, emon.Port.Cells feats, int length, int ink, int implausible, int body, int seal, int artifact) {
        // An OCR word whose feature row has these columns (-1 leaves one absent) and an engine confidence of 0, which means nothing.
        int w = Evidence.OwNew(ow, 1, 0, 0, 1000, 1000, 0, 900, 1000, 900, 0, 0, 0, length, -1, 0, -1);
        int f = Evidence.FeNew(feats, Evidence.EaOwords(), w);
        Evidence.OwSet(ow, w, Evidence.HdFeat(), f);
        Evidence.FeSet(feats, f, Evidence.XoConf(), 0);
        Evidence.FeSet(feats, f, Evidence.XoLength(), length);
        Evidence.FeSet(feats, f, Evidence.XoKinInk(), ink);
        Evidence.FeSet(feats, f, Evidence.XoImplausible(), implausible);
        Evidence.FeSet(feats, f, Evidence.XoBodyShare(), body);
        Evidence.FeSet(feats, f, Evidence.XoSeal(), seal);
        Evidence.FeSet(feats, f, Evidence.XoArtifact(), artifact);
        return f;
    }
    internal static int HtBlock(emon.Port.Cells ob, emon.Port.Cells ol, int firstWord, int nwords) {
        // A block of one paragraph of one line over `nwords` words from `first-word`; answers the block's row.
        int line = Evidence.OlNew(ol, 1, 0, 0, 1000, 1000, 0, 900, 1000, 900, 0, 0, firstWord, nwords);
        int b = Evidence.ObNew(ob, 1, 0, 0, 1000, 1000, Evidence.ObBlock(), -1, 0);
        int p = Evidence.ObNew(ob, 1, 0, 0, 1000, 1000, Evidence.ObParagraph(), b, 0);
        Evidence.ObSet(ob, b, Evidence.ObfFirst(), p);
        Evidence.ObSet(ob, b, Evidence.ObfCount(), 1);
        Evidence.ObSet(ob, p, Evidence.ObfFirst(), line);
        Evidence.ObSet(ob, p, Evidence.ObfCount(), 1);
        return b;
    }
    internal static int HtBlockScore(emon.Port.Cells hl, int b) {
        int n = Player.HlCount(hl);
        int i = 0;
        while (i < n) {
            if ((Player.HlGet(hl, i, 0) == Player.PlhOcrBlock()) && (Player.HlGet(hl, i, 2) == b)) {
                return i;
            }
            i += 1;
        }
        return -1;
    }
    internal static int HtBget(emon.Port.Cells hl, int b, int field) {
        // Cell `field` of the health row of OCR block `b`.
        int r = HtBlockScore(hl, b);
        return Player.HlGet(hl, r, field);
    }
    [Xunit.Fact]
    public static void TestOcrBlocks() {
        emon.Port.Cells words = emon.Port.NewCells();
        emon.Port.Cells fw = emon.Port.NewCells();
        emon.Port.Cells feats = emon.Port.NewCells();
        emon.Port.Cells cg = emon.Port.NewCells();
        emon.Port.Cells refs = emon.Port.NewCells();
        emon.Port.Cells hl = emon.Port.NewCells();
        emon.Port.Cells ob = emon.Port.NewCells();
        emon.Port.Cells ol = emon.Port.NewCells();
        emon.Port.Cells ow = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        // block 0: body text (ink 150, nothing implausible, 95 % on the body layer, no seal, no artifact); 1: over blank paper;
        // 2: under a seal; 3: soup; 4: watermark (artifact 900, light ink); 5: no ink columns at all, only the plausibility
        HtOcrWord(ow, feats, 5, 150, 0, 950, 0, 0);
        HtOcrWord(ow, feats, 6, 140, 0, 960, 0, 0);
        HtBlock(ob, ol, 0, 2);
        HtOcrWord(ow, feats, 6, 2, 0, 0, 0, 0);
        HtBlock(ob, ol, 2, 1);
        HtOcrWord(ow, feats, 6, 150, 0, 100, 900, 0);
        HtBlock(ob, ol, 3, 1);
        HtOcrWord(ow, feats, 6, 150, 800, 950, 0, 0);
        HtBlock(ob, ol, 4, 1);
        HtOcrWord(ow, feats, 6, 40, 0, 100, 0, 900);
        HtBlock(ob, ol, 5, 1);
        HtOcrWord(ow, feats, 6, -1, 0, -1, -1, -1);
        HtBlock(ob, ol, 6, 1);
        emon.Testport.AssertEq(Health.HlPage(1, cg, refs, fw, words, et, feats, ob, ol, ow, hl), 6, "six blocks scored");
        emon.Testport.AssertEq(Player.HlCount(hl), 6, "and six rows");
        int body = HtBget(hl, 0, Player.HlfScore());
        int blank = HtBget(hl, 2, Player.HlfScore());
        int seal = HtBget(hl, 4, Player.HlfScore());
        int soup = HtBget(hl, 6, Player.HlfScore());
        int mark = HtBget(hl, 8, Player.HlfScore());
        int bare = HtBget(hl, 10, Player.HlfScore());
        emon.Testport.AssertThat(body >= 900, "a body block is trusted");
        emon.Testport.AssertThat(blank < body, "blank paper scores under the body");
        emon.Testport.AssertThat(seal < body, "a seal scores under the body");
        emon.Testport.AssertThat(soup < body, "soup scores under the body");
        emon.Testport.AssertThat(mark < body, "a watermark scores under the body");
        emon.Testport.AssertThat(blank < 300, "blank paper is far under");
        emon.Testport.AssertThat(seal < 300, "a seal is far under");
        emon.Testport.AssertEq(bare, 1000, "a block with only a plausibility is scored on it: what is absent does not drag");
        emon.Testport.AssertEq(HtBget(hl, 0, Health.HobSeal()), 1000, "the body's seal component: 1000 - 0");
        emon.Testport.AssertEq(HtBget(hl, 4, Health.HobSeal()), 100, "the seal block's: 1000 - 900");
        emon.Testport.AssertEq(HtBget(hl, 4, Health.HobBody()), 100, "and its body share");
        emon.Testport.AssertEq(HtBget(hl, 8, Health.HobArtifact()), 100, "the watermark's artifact component");
        emon.Testport.AssertEq(HtBget(hl, 10, Health.HobInk()), -1, "an absent column is -1");
        emon.Testport.AssertEq(HtBget(hl, 10, Health.HobSeal()), -1, "and stays absent");
        emon.Testport.AssertEq(HtBget(hl, 10, Health.HobPlausible()), 1000, "while the plausibility is there");
        emon.Testport.AssertEq(HtBget(hl, 0, Health.HobScript()), -1, "no script column: ignored");
        emon.Testport.AssertEq(HtBget(hl, 0, Health.HobPlausible()), 1000, "the body's plausibility");
        emon.Testport.AssertEq(HtBget(hl, 0, Health.HobInk()), 1000, "the body's ink support: 150 is over `ink-ok`");
        emon.Testport.AssertEq(HtBget(hl, 2, Health.HobInk()), 0, "blank paper's: 2 is under `ink-bad`");
        // a second call overwrites
        Health.HlPage(1, cg, refs, fw, words, et, feats, ob, ol, ow, hl);
        emon.Testport.AssertEq(Player.HlCount(hl), 6, "no row is added");
    }
    internal static int HtRule(emon.Port.Cells rl, int page, int x0, int y0, int x1, int y1, int conf) {
        int r = Evidence.RlNew(rl, page, x0 - 0, y0 - 0, x1, y1, 0);
        Evidence.RlSet(rl, r, 6, x0);
        Evidence.RlSet(rl, r, 7, y0);
        Evidence.RlSet(rl, r, 8, x1);
        Evidence.RlSet(rl, r, 9, y1);
        Evidence.RlSet(rl, r, Evidence.RlfConf(), conf);
        return r;
    }
    [Xunit.Fact]
    public static void TestRegions() {
        emon.Port.Cells hl = emon.Port.NewCells();
        emon.Port.Cells im = emon.Port.NewCells();
        emon.Port.Cells rl = emon.Port.NewCells();
        // an image placement of 10 x 10 cm at (10000, 10000); a page of rules outside it, parallel to the axes within 10 centi-degrees
        Evidence.ImNew(im, 1, 10000, 10000, 20000, 20000, 5, 800, 800);
        HtRule(rl, 1, 1000, 1000, 50000, 1000, 900);
        HtRule(rl, 1, 1000, 5000, 50000, 5003, 950);
        HtRule(rl, 1, 1000, 1000, 1000, 40000, 850);
        // inside the image: skewed 1.5 degrees, far from parallel to each other
        HtRule(rl, 1, 11000, 12000, 19000, 12100, 700);
        HtRule(rl, 1, 11000, 15000, 19000, 15000, 700);
        HtRule(rl, 1, 12000, 11000, 12150, 19000, 600);
        emon.Testport.AssertEq(Health.HlRegions(1, im, rl, 920, 960, hl), 2, "R0 and one image");
        emon.Testport.AssertEq(Player.HlGet(hl, 0, 2), -1, "R0's subject");
        emon.Testport.AssertEq(Player.HlGet(hl, 0, Health.HrgRules()), 3, "three rules outside the image");
        emon.Testport.AssertEq(Player.HlGet(hl, 0, Health.HrgWitness()), 920, "the witness is the caller's");
        emon.Testport.AssertEq(Player.HlGet(hl, 0, Health.HrgPrecision()), 960, "and so is the precision");
        emon.Testport.AssertEq(Player.HlGet(hl, 0, Health.HrgConf()), 900, "the mean confidence of 900, 950, 850");
        emon.Testport.AssertThat(Player.HlGet(hl, 0, Health.HrgSkew()) >= 900, "parallel rules: the skew component is high");
        emon.Testport.AssertThat(Player.HlGet(hl, 0, Player.HlfScore()) >= 800, "R0's score is high");
        emon.Testport.AssertEq(Player.HlGet(hl, 1, 2), 0, "the image's subject is its row");
        emon.Testport.AssertEq(Player.HlGet(hl, 1, Health.HrgRules()), 3, "three rules inside it");
        emon.Testport.AssertEq(Player.HlGet(hl, 1, Health.HrgWitness()), -1, "no witness of its own");
        emon.Testport.AssertEq(Player.HlGet(hl, 1, Health.HrgPrecision()), 960, "it borrows the page's precision");
        emon.Testport.AssertEq(Player.HlGet(hl, 1, Health.HrgConf()), 666, "the mean of 700, 700, 600");
        emon.Testport.AssertThat(Player.HlGet(hl, 1, Health.HrgSkew()) < 1000, "a spread over 30 centi-degrees costs");
        emon.Testport.AssertThat(Player.HlGet(hl, 1, Player.HlfScore()) < Player.HlGet(hl, 0, Player.HlfScore()), "the image scores under R0");
        // again: overwritten
        Health.HlRegions(1, im, rl, 920, 960, hl);
        emon.Testport.AssertEq(Player.HlCount(hl), 2, "no row is added");
    }
    [Xunit.Fact]
    public static void TestTheTracersSymbolSupportJoinsTheInkSupport() {
        emon.Port.Cells feats = emon.Port.NewCells();
        emon.Port.Cells ow = emon.Port.NewCells();
        // ink 150 is full support alone; with the tracer saying none of the symbols has a text-like component it is half
        HtOcrWord(ow, feats, 5, 150, 0, 1000, 0, 0);
        HtOcrWord(ow, feats, 5, 150, 0, 1000, 0, 0);
        Evidence.FeSet(feats, 1, Evidence.XoCompRatio(), 0);
        HtOcrWord(ow, feats, 5, -1, 0, 1000, 0, 0);
        Evidence.FeSet(feats, 2, Evidence.XoCompRatio(), 400);
        emon.Testport.AssertEq(Health.HhWordScore(feats, 0), 1000, "the word with ink alone");
        emon.Testport.AssertThat(Health.HhWordScore(feats, 1) < Health.HhWordScore(feats, 0), "the same word with no component in its symbols scores under it");
        emon.Testport.AssertEq(Health.HhWordScore(feats, 2), 529, "a word with only the tracer's share is scored on it: 14e6 / 18500 = 756, times 1400 / 2000");
        emon.Testport.AssertEq(Health.HhWordScore(feats, -1), -1, "no feature row: no score");
    }
